/** A conversation summary (title auto-generated by Dify). */
export interface ChatConversation {
  id: string;
  name: string;
  /** Unix epoch seconds. */
  createdAt: number;
  /** Unix epoch seconds. */
  updatedAt: number;
}

/** One historical exchange: a user query paired with the assistant's answer. */
export interface ChatHistoryMessage {
  id: string;
  query: string;
  answer: string;
  /** Unix epoch seconds. */
  createdAt: number;
}
